/**
 * A factory to produce {@link JungLayoutProvider}s that can be used to layout 
 * {@link VisualGraph}s
 */
public class JungLayoutProviderFactory {

	//@formatter:offpublic static Set<JungLayoutProvider<V, E, G>> createLayouts<V, E, G>/* where V : VisualVertex where E : VisualEdge<V> where G : JungDirectedVisualGraph<V, E> */() {
	//@formatter:on

		Set<JungLayoutProvider<V, E, G>> providers = new();

		//@formatter:off
		providers.addAll(
			CollectionUtils.asSet(
				// create("DAG Layout", DAGLayout.class),
				create("Circle Layout", typeof(CircleLayout)),
				create("Spring Layout", typeof(SpringLayout)),
				create("KK Layout", typeof(KKLayout)),
				create("ISOM Layout", typeof(ISOMLayout))		
		));
		//@formatter:on

		return providers;
	}

	//@formatter:off
	/* @SuppressWarnings("rawtypes") */ // Layout should be templated; we are using it genericallypublic static JungLayoutProvider<V, E, G> create<V, E, G>/* where V : VisualVertex where E : VisualEdge<V> where G : JungDirectedVisualGraph<V, E> */(string name, Class<Layout> layoutClass) {
	//@formatter:on

		JungLayoutProvider<V, E, G> provider = new JungLayoutProvider<V, E, G>() {

			/* @Override */
			public string getLayoutName() {
				return name;
			}

			/* @Override */
			protected Layout<V, E> createLayout(G g) {

				try {
					Constructor<object> c = layoutClass.getConstructor(typeof(Graph));

					// we are using the interface to this factory to get compile-time 
					// enforcement of types; at this point we cannot enforce types using a 
					// class object to create a new layout
					/* @SuppressWarnings("unchecked") */
					Layout<V, E> l = (Layout<V, E>) c.newInstance(g);
					return l;
				}
				catch (Exception e) {
					Msg.error(typeof(JungLayoutProviderFactory),
						"Unable to construct layout: " + layoutClass, e);
				}
				return null;
			}

		};
		return provider;
	}
}
